import * as THREE from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
const $=id=>document.getElementById(id),all=q=>[...document.querySelectorAll(q)];
let model,scene,camera,renderer,controls,parts=[],selected=null,playing=false,speed=1,mode='explore',step=0,explodeTarget=0,angle=0,filter='all',labelsOn=false,ready=false;
let needsRender=true;
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');let reduced=motionPreference.matches;motionPreference.addEventListener('change',e=>{reduced=e.matches;});
const status=s=>{$('status-message').textContent=s;};
const steps=[['准备拆卸','演示开始前停机。先拆紧固件，再拆箱盖、端盖和轴系。'],['松开合箱螺栓','交叉、分次解除紧固；这里将螺栓提升以方便观察。'],['打开上箱盖','移开检查孔盖与上箱盖，露出轴系。'],['拆下端盖与油封','拆开轴承端盖，解除轴端定位和密封。'],['分离轴承','展示轴承与轴的配合关系；实际拆装需使用专用工具。'],['移出三根轴系','逐一观察输入、中间、输出轴及其支撑关系。'],['拆分齿轮与平键','分离可拆卸大齿轮与平键。小齿轮和轴为一体结构。'],['认识箱体与全套零件','完整爆炸状态。点击任一零件查看讲解，或反向逐步装配。']];
all('[data-tab]').forEach(b=>b.addEventListener('click',()=>showTab(b.dataset.tab)));
all('[data-go]').forEach(b=>b.addEventListener('click',()=>showTab(b.dataset.go)));
function showTab(id){all('.tab-panel').forEach(p=>p.hidden=p.id!==id);all('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===id));if(id==='explore')resize();else pause();}
function pause(){playing=false;$('play').textContent='▶';$('play').setAttribute('aria-label','播放传动动画');}
function setExplode(v){explodeTarget=v;$('explode').value=Math.round(v*100);$('explode-value').value=Math.round(v*100)+'%';if(v>0){pause();if($('housing-mode').value==='open'){$('housing-mode').value='solid';applyVisibility();}}fitDistance(v);}
function fitDistance(v){if(!camera)return;const target=new THREE.Vector3(30,25*v,0);const direction=camera.position.clone().sub(controls.target).normalize();const narrow=$('viewport').clientWidth<$('viewport').clientHeight?1.25:1;camera.position.copy(target).addScaledVector(direction,(680+700*v)*narrow);controls.target.copy(target);controls.update();}
$('explode').addEventListener('input',e=>{setExplode(+e.target.value/100);status(explodeTarget?'爆炸视图已暂停传动。可拖动滑块观察装配关系。':'已复原，可播放传动动画。');});
$('explode-all').onclick=()=>{setExplode(1);status('全部展开。旋转模型，查看每个零件的装配位置。');};
$('assemble-all').onclick=()=>{setExplode(0);step=0;updateStep();status('已复原装配。');};
$('speed').oninput=e=>{speed=+e.target.value;$('speed-value').value=speed.toFixed(1)+'×';};
$('play').onclick=()=>{if(!ready)return;if(playing){pause();return;}if(explodeTarget>0||step>0){setExplode(0);step=0;updateStep();status('已复原后播放。显示为慢动作，三轴保持 1 : −1/4 : 1/16 的转速关系。');}else status('为便于观察，输入轴以约 12 r/min 慢放；面板显示设计工况转速。');playing=true;$('play').textContent='Ⅱ';$('play').setAttribute('aria-label','暂停传动动画');};
all('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;all('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));$('free-controls').hidden=mode!=='explore';$('assembly-controls').hidden=mode!=='assembly';$('mode-label').textContent=mode==='assembly'?'逐步拆装':'结构探索';pause();setExplode(0);step=0;updateStep();if(mode==='explore')status('自由探索：拖动旋转、点击零件，或展开查看装配关系。');if(mode==='assembly'){$('housing-mode').value='solid';applyVisibility();status('按“下一步”逐步拆卸；按“上一步”反向装配。');}});
$('step-next').onclick=()=>{step=Math.min(7,step+1);pause();updateStep();};$('step-prev').onclick=()=>{step=Math.max(0,step-1);updateStep();};
function updateStep(){$('step-number').textContent=String(step).padStart(2,'0')+' / 07';$('step-title').textContent=steps[step][0];$('step-copy').textContent=steps[step][1];$('step-prev').disabled=step===0;$('step-next').disabled=step===7;if(mode==='assembly')fitDistance(step/7);}
const groupNames={shaft:'轴系',gear:'齿轮',bearing:'轴承',housing:'箱体',cover:'端盖与附件',seal:'密封',fastener:'连接件'};
const symbols={"shaft": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 10h18v4H3Z\"/><path d=\"M8 7v10m8-10v10\"/></svg>", "gear": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m9 3-1 3-3 1-2 5 2 5 3 1 1 3h6l1-3 3-1 2-5-2-5-3-1-1-3Z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>", "bearing": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/></svg>", "housing": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m12 3 9 5v9l-9 5-9-5V8Z\"/><path d=\"m3 8 9 5 9-5M12 13v9M7.5 5.5l9 5\"/></svg>", "cover": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"3\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/></svg>", "seal": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"8\"/><circle cx=\"12\" cy=\"12\" r=\"6\"/></svg>", "fastener": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M8 3h8v4H8Zm2 4v14h4V7M9 11h6m-6 4h6m-6 4h6\"/></svg>"};
function renderList(){if(!model)return;const q=$('part-search').value.trim();let list=model.parts.filter(p=>(!q||p.name.includes(q)||p.spec.toLowerCase().includes(q.toLowerCase()))&&(filter==='all'||(filter==='transmission'?['shaft','gear','bearing'].includes(p.category):['housing','cover','seal'].includes(p.category))));$('parts-list').innerHTML='';let prev='';for(const p of list){if(p.category!==prev){let g=document.createElement('div');g.className='group-label';g.textContent=groupNames[p.category];$('parts-list').append(g);prev=p.category;}const b=document.createElement('button');b.className='part-item'+(selected?.id===p.id?' active':'');b.dataset.id=p.id;b.setAttribute('aria-pressed',String(selected?.id===p.id));b.innerHTML=`<span class="part-icon">${symbols[p.category]}</span><span>${p.name}</span><span class="part-number">${String(model.parts.indexOf(p)+1).padStart(2,'0')}</span>`;b.onclick=()=>select(p.id);$('parts-list').append(b);}if(!list.length){const t=document.createElement('p');t.className='detail-description';t.textContent='没有匹配的零件';$('parts-list').append(t);}}
$('part-search').oninput=renderList;all('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;all('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderList();});
function select(id){needsRender=true;const p=model.parts.find(p=>p.id===id);if(!p)return;selected=p;for(const o of parts){o.mesh.material.emissive.set(o.data.id===id?'#226ad8':'#000000');o.mesh.material.emissiveIntensity=o.data.id===id?.32:0;}renderList();$('detail-content').innerHTML=`<p class="detail-index">${String(model.parts.indexOf(p)+1).padStart(2,'0')} / ${p.id.toUpperCase()}</p><div class="detail-symbol">${symbols[p.category]}</div><h3>${p.name}</h3><p class="detail-description">${p.description}</p><div class="detail-spec">${p.spec}</div><div class="material-label">材料 / ${p.material}</div><button class="speak-button" id="speak">◖)) 朗读讲解</button>`;$('speak').onclick=()=>speak(p);$('selection-label').hidden=false;$('selection-label').textContent=p.name;const obj=parts.find(x=>x.data.id===id);if(obj&&!obj.mesh.visible){obj.forceVisible=true;obj.mesh.visible=true;status('已显示选中的隐藏零件；更改箱体显示可恢复。');}}
function speak(p){if(!('speechSynthesis'in window)){status('当前浏览器不支持语音朗读，完整文字讲解已显示。');return;}if(speechSynthesis.speaking){speechSynthesis.cancel();$('speak').textContent='◖)) 朗读讲解';return;}const u=new SpeechSynthesisUtterance(p.name+'。'+p.description+'。'+p.spec);u.lang='zh-CN';u.rate=.95;const voice=speechSynthesis.getVoices().find(v=>/^zh[-_]CN/i.test(v.lang))||speechSynthesis.getVoices().find(v=>v.lang.startsWith('zh'));if(voice)u.voice=voice;u.onend=()=>{if($('speak'))$('speak').textContent='◖)) 朗读讲解';};u.onerror=()=>status('中文语音暂不可用，请检查设备语音设置；文字讲解仍可阅读。');speechSynthesis.speak(u);$('speak').textContent='■ 停止朗读';}
function applyVisibility(){needsRender=true;const v=$('housing-mode').value;for(const o of parts){o.forceVisible=false;const housing=['housing_top','housing_base','inspection','breather'].includes(o.data.id)||o.data.id.startsWith('bolt');o.mesh.visible=!(housing&&(v==='hidden'||v==='open'&&o.data.id!=='housing_base'));const translucent=housing&&v==='transparent';o.mesh.material.transparent=translucent;o.mesh.material.opacity=translucent?.16:1;o.mesh.material.depthWrite=!translucent;o.mesh.renderOrder=translucent?2:0;}}
$('housing-mode').onchange=applyVisibility;$('labels-toggle').onchange=e=>{labelsOn=e.target.checked;needsRender=true;};
$('home-view').onclick=()=>view('home');$('top-view').onclick=()=>view('top');$('front-view').onclick=()=>view('front');
function view(v){if(!camera)return;controls.target.set(30,0,0);camera.up.set(0,1,0);if(v==='home')camera.position.set(390,330,460);if(v==='top'){camera.position.set(30,620,.1);camera.up.set(0,0,-1);}if(v==='front')camera.position.set(30,25,650);fitDistance(mode==='assembly'?step/7:explodeTarget);controls.update();}
$('fullscreen').onclick=async()=>{const el=document.querySelector('.viewer-panel');try{if(document.fullscreenElement)await document.exitFullscreen();else if(el.requestFullscreen)await el.requestFullscreen();else status('当前设备不支持浏览器全屏，可横屏放大观察。');}catch{status('当前浏览器未允许全屏。');}};
$('calc-rpm').oninput=e=>{const n=+e.target.value;$('calc-rpm-value').value=n+' r/min';$('calc-input').textContent=n;$('calc-middle').textContent=(n/4).toFixed(1).replace('.0','');$('calc-output').textContent=(n/16).toFixed(2).replace(/\.00$/,'');};
function resize(){needsRender=true;if(!renderer)return;const el=$('viewport');const w=el.clientWidth,h=el.clientHeight;if(!w||!h)return;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();}
async function init(){try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,powerPreference:'high-performance'});}catch(err){$('loading').hidden=true;$('webgl-error').hidden=false;return;}
renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setClearColor('#eaf2fc',0);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;$('viewport').appendChild(renderer.domElement);
scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(38,1,1,3000);controls=new OrbitControls(camera,renderer.domElement);controls.addEventListener('change',()=>{needsRender=true;});controls.enableDamping=true;controls.dampingFactor=.07;controls.minDistance=220;controls.maxDistance=2200;controls.maxPolarAngle=Math.PI*.93;view('home');resize();new ResizeObserver(resize).observe($('viewport'));
scene.add(new THREE.HemisphereLight('#ffffff','#a8adb5',2.2));const light=new THREE.DirectionalLight('#ffffff',3);light.position.set(-180,460,270);light.castShadow=true;light.shadow.mapSize.set(1024,1024);Object.assign(light.shadow.camera,{left:-450,right:450,top:450,bottom:-450,near:1,far:1500});light.shadow.bias=-.001;scene.add(light);const fill=new THREE.DirectionalLight('#dceaff',1.8);fill.position.set(300,100,-300);scene.add(fill);
const floor=new THREE.Mesh(new THREE.PlaneGeometry(1800,1800),new THREE.ShadowMaterial({opacity:.09}));floor.rotation.x=-Math.PI/2;floor.position.y=-134;floor.receiveShadow=true;scene.add(floor);const grid=new THREE.GridHelper(1500,50,'#aeb4bd','#c8cdd5');grid.position.y=-134.5;grid.material.transparent=true;grid.material.opacity=.16;scene.add(grid);const appearance=matchMedia('(prefers-color-scheme: dark)');function updateSceneAppearance(){grid.material.opacity=appearance.matches?.09:.16;floor.material.opacity=appearance.matches?.22:.09;needsRender=true;}appearance.addEventListener('change',updateSceneAppearance);updateSceneAppearance();
try{const res=await fetch('assets/model.json');if(!res.ok)throw new Error('模型数据未找到');model=await res.json();$('part-count').textContent=model.parts.length;let loaded=0;const queue=[...model.parts];await Promise.all(Array.from({length:5},async()=>{while(queue.length){const p=queue.shift();const r=await fetch('assets/'+p.id+'.mesh');if(!r.ok)throw new Error(p.name+'加载失败');const data=await r.arrayBuffer(),head=new DataView(data),n=head.getUint32(0,true),ni=head.getUint32(4,true);const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(new Float32Array(data,8,n*3),3));geometry.setIndex(new THREE.BufferAttribute(new Uint32Array(data,8+n*12,ni),1));geometry.computeVertexNormals();geometry.computeBoundingSphere();const mat=new THREE.MeshStandardMaterial({color:p.category==='housing'?'#a6adb6':p.category==='gear'?'#b3bcc8':p.category==='cover'?'#64707d':p.color,metalness:p.category==='gear'?.62:p.category==='housing'?.2:.65,roughness:p.category==='housing'?.7:.38});const mesh=new THREE.Mesh(geometry,mat);mesh.position.fromArray(p.position);mesh.castShadow=true;mesh.receiveShadow=true;mesh.userData.partId=p.id;scene.add(mesh);parts.push({mesh,data:p,base:new THREE.Vector3(...p.position),offset:new THREE.Vector3(...p.explode),amount:0});$('load-progress').textContent=`已就位 ${++loaded} / ${model.parts.length} 个零件`;}}));
renderList();applyVisibility();for(const id of ['input','middle','output','gear1','gear2']){const p=parts.find(x=>x.data.id===id);const el=document.createElement('span');el.className='model-label';el.textContent=p.data.name;el.hidden=true;$('viewport').append(el);p.label=el;}
ready=true;needsRender=true;select('gear1');$('loading').hidden=true;status('模型已就绪。默认打开上盖，便于观察内部结构。');
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();let down=null;renderer.domElement.addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY,time:performance.now()};});renderer.domElement.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down.x,e.clientY-down.y)>7||performance.now()-down.time>700)return;const rect=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);raycaster.setFromCamera(pointer,camera);const visible=parts.filter(p=>p.mesh.visible&&p.mesh.material.opacity>.3).map(p=>p.mesh);const hit=raycaster.intersectObjects(visible,false)[0];if(hit)select(hit.object.userData.partId);});
}catch(e){$('loading').innerHTML='<b>模型加载未完成</b><small>请刷新重试，或在工程资料页下载 STEP 模型。</small>';status(e.message);console.error(e);}
let last=performance.now();function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-last)/1000,.05);last=now;if(playing&&parts.every(o=>o.amount<.002))angle+=dt*1.256637*speed;let moving=false;for(const o of parts){let target=mode==='assembly'?(step>o.data.step?1:0):explodeTarget;if(o.data.id==='housing_base'&&mode==='assembly'&&step<7)target=0;const k=reduced?1:Math.min(1,dt*7);o.amount+= (target-o.amount)*k;if(Math.abs(o.amount-target)>.001)moving=true;o.mesh.position.copy(o.base).addScaledVector(o.offset,o.amount);if(o.data.spin){if(o.data.id.startsWith('key')){const x0=o.data.id==='key1'?-16:96;const y=o.base.y;const a=angle*o.data.spin;o.mesh.position.x=x0-y*Math.sin(a)+o.offset.x*o.amount;o.mesh.position.y=y*Math.cos(a)+o.offset.y*o.amount;}o.mesh.rotation.z=angle*o.data.spin;}if(o.label){o.label.hidden=!labelsOn||!o.mesh.visible;const pt=o.mesh.position.clone().add(new THREE.Vector3(0,35,0)).project(camera);o.label.style.left=(pt.x*.5+.5)*$('viewport').clientWidth+'px';o.label.style.top=(-pt.y*.5+.5)*$('viewport').clientHeight+'px';if(pt.z>1)o.label.hidden=true;}}floor.position.y=-134-105*(mode==='assembly'?step===7?1:0:explodeTarget);grid.position.y=floor.position.y-.5;controls.update();if(!$('explore').hidden&&(needsRender||playing||moving)){renderer.render(scene,camera);needsRender=false;}}
requestAnimationFrame(frame);window.__gearLab={getState:()=>({ready,partCount:parts.length,selected:selected?.id,playing,step,mode,explodeTarget}),select,view};}
init();updateStep();
